/**
 * Private object storage for uploaded files. Keys are generated by the server
 * from UUIDs only (never from file names or user input).
 */
export interface ObjectStorage {
  put(key: string, data: Buffer, contentType: string): Promise<void>;
  /**
   * Writes the file only if nothing is stored under `key` yet. Returns false (and changes nothing) if a file
   * is already there. Used for photo originals so a stored original can never be replaced.
   */
  putIfAbsent(key: string, data: Buffer, contentType: string): Promise<boolean>;
  get(key: string): Promise<Buffer | null>;
  /** Removes a stored file. Removing a file that is already gone is not an error. */
  delete(key: string): Promise<void>;
}

const KEY = /^org\/[0-9a-f-]{36}\/photos\/[0-9a-f-]{36}(\/(original|preview))?$/;

export function photoKey(orgId: string, photoId: string): string {
  // UUIDs are compared case-insensitively by the database; file names always use the lowercase form.
  const key = `org/${orgId.toLowerCase()}/photos/${photoId.toLowerCase()}`;
  if (!KEY.test(key)) throw new Error("invalid storage key");
  return key;
}

export function assertValidKey(key: string): void {
  if (!KEY.test(key)) throw new Error("invalid storage key");
}
